css:
.cvfsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2433;
    background: linear-gradient(160deg, #eef1f6 0%, #e4e9f1 100%);
    border-radius: 18px;
}

.cvfsim-container * {
    box-sizing: border-box;
}

.cvfsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16213b 0%, #1f3a5f 55%, #0f6e6e 100%);
    color: #f3f7fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 33, 59, 0.32);
}

.cvfsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cvfsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #9fe3df;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.cvfsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d8e3ef;
}

.cvfsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #29405f;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cvfsim-period-counter #currentDay,
.cvfsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16213b;
}

.cvfsim-round-name {
    background: #d3e7e6;
    color: #0f5252;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cvfsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4711;
    background: #fbe9d8;
    padding: 4px 12px;
    border-radius: 999px;
}

.cvfsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cvfsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6deea;
    box-shadow: 0 4px 14px rgba(22, 33, 59, 0.06);
    border-top: 4px solid #1f3a5f;
}

.cvfsim-card-culture { border-top-color: #0f6e6e; }
.cvfsim-card-throughput { border-top-color: #1f3a5f; }
.cvfsim-card-trust { border-top-color: #2f8f5b; }
.cvfsim-card-role { border-top-color: #c2871a; }

.cvfsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5f7184;
}

.cvfsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16213b;
}

.cvfsim-card-culture .cvfsim-value { color: #0f6e6e; }
.cvfsim-card-throughput .cvfsim-value { color: #1f3a5f; }
.cvfsim-card-trust .cvfsim-value { color: #2f8f5b; }
.cvfsim-card-role .cvfsim-value { color: #c2871a; }

.cvfsim-sublabel {
    font-size: 0.76rem;
    color: #71839a;
    line-height: 1.35;
}

.cvfsim-kpi-low .cvfsim-value { color: #c0392b; }
.cvfsim-kpi-target .cvfsim-value { color: #2f8f5b; }

.cvfsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16213b;
    color: #e9f1f7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cvfsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.cvfsim-budget-over #budgetDisplay {
    color: #ff9b8a;
}

.cvfsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #0f6e6e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 33, 59, 0.05);
}

.cvfsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cvfsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16213b;
    margin-bottom: 6px;
}

.cvfsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3a4d;
}

.cvfsim-briefing-text strong { color: #0f6e6e; }
.cvfsim-briefing-text em { color: #9a4711; font-style: italic; }

.cvfsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6deea;
    box-shadow: 0 4px 14px rgba(22, 33, 59, 0.06);
}

.cvfsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16213b;
    border-bottom: 2px solid #e4e9f1;
    padding-bottom: 8px;
}

.cvfsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243349;
    margin: 14px 0 6px;
}

.cvfsim-container select,
.cvfsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6c5d8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f9fc;
    color: #1b2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cvfsim-container select:focus,
.cvfsim-container input[type="number"]:focus {
    outline: none;
    border-color: #0f6e6e;
    box-shadow: 0 0 0 3px rgba(15, 110, 110, 0.16);
}

.cvfsim-container select option {
    background-color: #ffffff;
    color: #1b2433;
}

.cvfsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0f6e6e;
}

.cvfsim-range-readout,
.cvfsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f5a5a;
    margin-top: 4px;
}

.cvfsim-range-readout span:last-child,
.cvfsim-alloc-readout span:nth-child(2) {
    color: #2f8f5b;
    font-weight: 800;
}

.cvfsim-hint {
    font-size: 0.8rem;
    color: #71839a;
    margin-top: 4px;
    line-height: 1.4;
}

.cvfsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.cvfsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f7f7;
    border: 1px solid #d8e7e6;
    border-radius: 9px;
    padding: 8px 12px;
}

.cvfsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #243349;
}

.cvfsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.cvfsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cvfsim-container .btn-primary {
    background: linear-gradient(135deg, #0f6e6e 0%, #1f3a5f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(15, 110, 110, 0.28);
}

.cvfsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.cvfsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6c5d8;
    color: #5f7184;
}

.cvfsim-coach {
    background: #16213b;
    color: #e9f1f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 33, 59, 0.24);
}

.cvfsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7fd6d0;
    margin-bottom: 8px;
}

.cvfsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cvfsim-coach-body strong { color: #ffd98a; }
.cvfsim-coach-body em { color: #ffc1ad; font-style: italic; }

.cvfsim-history,
.cvfsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6deea;
    box-shadow: 0 4px 14px rgba(22, 33, 59, 0.06);
}

.cvfsim-history h3,
.cvfsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16213b;
}

.cvfsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243349;
}

.cvfsim-container table#usfHistoryTable th {
    background: #e8eef5;
    color: #16213b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2dde9;
}

.cvfsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f7;
}

.cvfsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fafc;
}

.cvfsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cvfsim-container {
        padding: 14px;
    }
    .cvfsim-header h1 {
        font-size: 1.7rem;
    }
    .cvfsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cvfsim-value {
        font-size: 2rem;
    }
    .cvfsim-clock {
        margin-left: 0;
    }
    .cvfsim-period-counter {
        font-size: 0.88rem;
    }
    .cvfsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cvfsim-alloc-row {
        flex-wrap: wrap;
    }
    .cvfsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .cvfsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, cvfsim) ---- */
.cvfsim-completion { padding: 8px 4px 4px; }
.cvfsim-cm-head { text-align: center; margin-bottom: 16px; }
.cvfsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a52; }
.cvfsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b9b7d; }
.cvfsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #11203b; }
.cvfsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.cvfsim-cm-yes { background: rgba(31,122,82,0.14); color: #1a7059; border: 1px solid rgba(31,122,82,0.5); }
.cvfsim-cm-no { background: rgba(192,86,31,0.12); color: #b0521f; border: 1px solid rgba(192,86,31,0.45); }
.cvfsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.cvfsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(42,74,122,0.08); border: 1px solid rgba(42,74,122,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.cvfsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2a4a7a; }
.cvfsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.cvfsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #11203b; }
.cvfsim-cm-insights { margin: 0; padding-left: 20px; }
.cvfsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

