(function() {
    'use strict';

    class CompetingValuesAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Competing Values`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD; budget in thousands).
            this.START_CULTURE = 22;       // heavily Clan/Adhocracy, misaligned to the mandate
            this.START_THROUGHPUT = 18;    // ~3,300 of 10,000 cases/mo, low scaled-ops readiness
            this.START_TRUST = 40;         // 98% satisfaction + clan, but fragile
            this.START_ROLE = 15;          // no behavioral complexity demonstrated yet
            this.TARGET_THROUGHPUT = 70;   // credible Q4 trajectory
            this.WIN_COMPOSITE = 68;       // "both/and leader" win bar
            this.BUDGET_CAP = 2000;        // USD 2.0M transition budget, in thousands (binds on the 120-hire path)
            this.SLA_PENALTY = 250;        // USD 250k modelled SLA-breach hit (within 1.5M/yr cap)
            this.ATTN_BUDGET = 100;        // leadership-attention points

            // Concept truths.
            this.TRUE_DIAGNOSIS = `imbalanced`;
            this.TRUE_GAP = `markethier`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    culture: this.START_CULTURE,
                    throughput: this.START_THROUGHPUT,
                    trust: this.START_TRUST,
                    role: this.START_ROLE,
                    budgetUsed: 0,
                    slaPenalty: 0,
                    overRotated: false,
                    whipsawed: false,
                    regulatoryEvent: false,
                    cultureHistory: [this.START_CULTURE],
                    throughputHistory: [this.START_THROUGHPUT],
                    trustHistory: [this.START_TRUST],
                    roleHistory: [this.START_ROLE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    diagnosis: `imbalanced`,
                    gap: `markethier`,
                    naming: 60,
                    control: 55,
                    flex: 45,
                    move1: `triage`,
                    move2: `dashboard`,
                    move3: `craftlane`,
                    portfolio: `spanning`,
                    ceo: `commit`,
                    engineers: `enroll`,
                    adverse: `keepqa`,
                    recovery: `recalibrate`,
                    sequence: `phased`,
                    kpi: `balanced`,
                    steadiness: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const diag = document.getElementById(`diagnosisInput`);
                const gap = document.getElementById(`gapInput`);
                const nm = document.getElementById(`namingInput`);
                if (diag) decisions.diagnosis = diag.value;
                if (gap) decisions.gap = gap.value;
                if (nm) decisions.naming = parseInt(nm.value, 10);
                if (!Number.isFinite(decisions.naming) || decisions.naming < 0 || decisions.naming > 100) {
                    warn(`warn_naming_range`); return false;
                }
            } else if (round === 2) {
                const ctrl = document.getElementById(`controlInput`);
                const flex = document.getElementById(`flexInput`);
                if (ctrl) decisions.control = parseFloat(ctrl.value);
                if (flex) decisions.flex = parseFloat(flex.value);
                if (!Number.isFinite(decisions.control) || !Number.isFinite(decisions.flex) || decisions.control < 0 || decisions.flex < 0) {
                    warn(`warn_attn_negative`); return false;
                }
                const total = Math.round(decisions.control + decisions.flex);
                if (total !== this.ATTN_BUDGET) {
                    warn(`warn_attn_total`); return false;
                }
                const m1 = document.getElementById(`move1Input`);
                const m2 = document.getElementById(`move2Input`);
                const m3 = document.getElementById(`move3Input`);
                if (m1) decisions.move1 = m1.value;
                if (m2) decisions.move2 = m2.value;
                if (m3) decisions.move3 = m3.value;
            } else if (round === 3) {
                const pf = document.getElementById(`portfolioInput`);
                const ceo = document.getElementById(`ceoInput`);
                const eng = document.getElementById(`engineersInput`);
                const adv = document.getElementById(`adverseInput`);
                if (pf) decisions.portfolio = pf.value;
                if (ceo) decisions.ceo = ceo.value;
                if (eng) decisions.engineers = eng.value;
                if (adv) decisions.adverse = adv.value;
            } else if (round === 4) {
                const rec = document.getElementById(`recoveryInput`);
                const seq = document.getElementById(`sequenceInput`);
                const kpi = document.getElementById(`kpiInput`);
                const st = document.getElementById(`steadinessInput`);
                if (rec) decisions.recovery = rec.value;
                if (seq) decisions.sequence = seq.value;
                if (kpi) decisions.kpi = kpi.value;
                if (st) decisions.steadiness = parseInt(st.value, 10);
                if (!Number.isFinite(decisions.steadiness) || decisions.steadiness < 0 || decisions.steadiness > 100) {
                    warn(`warn_steadiness_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas across the four KPIs, plus resource usage.
            let cultureDelta = 0, throughputDelta = 0, trustDelta = 0, roleDelta = 0;
            let spend = 0, slaHit = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: imbalanced (add Market/Hierarchy), not broken / fine / already-market.
                if (d.diagnosis === this.TRUE_DIAGNOSIS) {
                    cultureDelta += 14; trustDelta += 6; roleDelta += 2; coachKey = `coach_r1_imbalanced`;
                } else if (d.diagnosis === `broken`) {
                    cultureDelta += 2; trustDelta -= 12; coachKey = `coach_r1_broken`;
                } else if (d.diagnosis === `fine`) {
                    cultureDelta -= 10; throughputDelta -= 6; coachKey = `coach_r1_fine`;
                } else {
                    cultureDelta -= 8; trustDelta -= 6; coachKey = `coach_r1_market`;
                }

                // Name the two quadrants to ADD.
                if (d.gap === this.TRUE_GAP) {
                    cultureDelta += 12; throughputDelta += 4;
                    if (d.diagnosis === this.TRUE_DIAGNOSIS) coachKey = `coach_r1_sharp`;
                } else if (d.gap === `hieronly` || d.gap === `marketonly`) {
                    cultureDelta += 2; trustDelta -= 4; coachKey = `coach_r1_partial`;
                } else {
                    cultureDelta -= 10; throughputDelta -= 6; coachKey = `coach_r1_clanadhoc`;
                }

                // Naming the contradiction is itself an intervention.
                if (d.naming >= 60) { cultureDelta += 6; trustDelta += 3; }
                else if (d.naming <= 25) { cultureDelta -= 6; trustDelta -= 2; coachKey = `coach_r1_pretend`; }

                summaryKey = (d.diagnosis === this.TRUE_DIAGNOSIS && d.gap === this.TRUE_GAP) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set the balance. The both/and zone is a deliberate tilt toward control WITHOUT
                // breaking the clan: control in 50-65 scores best. Over-rotation (>=75) loses people.
                const ctrl = d.control;
                if (ctrl >= 50 && ctrl <= 65) {
                    throughputDelta += 12; cultureDelta += 8; trustDelta += 4; roleDelta += 2; coachKey = `coach_r2_balanced`;
                } else if (ctrl >= 75) {
                    // Over-rotate to Market/Hierarchy: number moves, clan breaks.
                    throughputDelta += 14; cultureDelta += 4; trustDelta -= 16; ds.overRotated = true; coachKey = `coach_r2_overrotate`;
                } else if (ctrl >= 66 && ctrl < 75) {
                    throughputDelta += 12; cultureDelta += 5; trustDelta -= 6; coachKey = `coach_r2_tooaggressive`;
                } else if (ctrl >= 35 && ctrl < 50) {
                    throughputDelta += 5; cultureDelta += 4; trustDelta += 5; coachKey = `coach_r2_clanlean`;
                } else {
                    // Stay in Clan/Adhocracy: trust holds, throughput gap missed, SLA bites.
                    throughputDelta -= 6; trustDelta += 3; slaHit += this.SLA_PENALTY; coachKey = `coach_r2_stayclan`;
                }

                // Move 1 — capacity mechanism.
                switch (d.move1) {
                    case `triage`: spend += 700; throughputDelta += 10; cultureDelta += 3; break;
                    case `callcenter`: spend += 600; throughputDelta += 12; trustDelta -= 12; coachKey = `coach_r2_callcenter`; break;
                    case `hireonly`: spend += 1400; throughputDelta += 4; coachKey = `coach_r2_hireonly`; break;
                }

                // Move 2 — make results visible (external/Market).
                switch (d.move2) {
                    case `dashboard`: spend += 400; throughputDelta += 8; roleDelta += 3; break;
                    case `nodash`: throughputDelta -= 6; slaHit += this.SLA_PENALTY; coachKey = `coach_r2_nodash`; break;
                    case `secretmetrics`: spend += 200; throughputDelta += 4; trustDelta -= 8; coachKey = `coach_r2_secret`; break;
                }

                // Move 3 — protect what earns the 98% (and the non-negotiable control).
                switch (d.move3) {
                    case `craftlane`: spend += 500; trustDelta += 12; cultureDelta += 4; break;
                    case `nolane`: trustDelta -= 8; coachKey = `coach_r2_nolane`; break;
                    case `cutqa`: spend -= 0; throughputDelta += 6; trustDelta -= 6; ds.regulatoryEvent = true; coachKey = `coach_r2_cutqa`; break;
                }

                summaryKey = (ctrl >= 50 && ctrl <= 65 && d.move1 !== `hireonly` && d.move3 === `craftlane` && d.move3 !== `cutqa`) ? `sum_r2_good` : (ds.overRotated || ds.regulatoryEvent ? `sum_r2_overrotate` : `sum_r2_weak`);
            } else if (round === 3) {
                // Choose roles — behavioral complexity beats single-style comfort.
                switch (d.portfolio) {
                    case `spanning`: roleDelta += 20; cultureDelta += 6; throughputDelta += 4; trustDelta += 4; coachKey = `coach_r3_spanning`; break;
                    case `clanonly`: roleDelta += 2; trustDelta += 6; throughputDelta -= 8; slaHit += this.SLA_PENALTY; coachKey = `coach_r3_clanonly`; break;
                    case `marketonly`: roleDelta += 4; throughputDelta += 8; trustDelta -= 14; ds.overRotated = true; coachKey = `coach_r3_marketonly`; break;
                    case `hieronly`: roleDelta += 4; throughputDelta += 4; cultureDelta += 2; trustDelta -= 8; coachKey = `coach_r3_hieronly`; break;
                }

                // Pressure A — the CEO.
                switch (d.ceo) {
                    case `commit`: throughputDelta += 8; roleDelta += 4; break;
                    case `promise`: throughputDelta += 4; trustDelta -= 8; coachKey = `coach_r3_promise`; break;
                    case `deflect`: throughputDelta -= 10; trustDelta -= 4; coachKey = `coach_r3_deflect`; break;
                }

                // Pressure B — the two key engineers (30% of relationships).
                switch (d.engineers) {
                    case `enroll`: trustDelta += 14; cultureDelta += 4; roleDelta += 3; break;
                    case `ignore`: trustDelta -= 18; cultureDelta -= 6; coachKey = `coach_r3_ignore`; break;
                    case `exempt`: trustDelta += 2; cultureDelta -= 6; coachKey = `coach_r3_exempt`; break;
                }

                // Pressure C — the near-miss adverse-event report (21 CFR 820).
                switch (d.adverse) {
                    case `keepqa`: roleDelta += 6; trustDelta += 4; coachKey = (d.portfolio === `spanning`) ? `coach_r3_spanning` : coachKey; break;
                    case `speed`: throughputDelta += 4; trustDelta -= 10; ds.regulatoryEvent = true; coachKey = `coach_r3_speed`; break;
                    case `freezeall`: throughputDelta -= 12; coachKey = `coach_r3_freeze`; break;
                }

                summaryKey = (d.portfolio === `spanning` && d.engineers === `enroll` && d.adverse === `keepqa`) ? `sum_r3_good` : (ds.overRotated || d.portfolio === `marketonly` ? `sum_r3_overrotate` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recover the plan — recalibrate, do not whipsaw.
                switch (d.recovery) {
                    case `recalibrate`: cultureDelta += 8; throughputDelta += 8; trustDelta += 10; roleDelta += 4; coachKey = `coach_r4_recalibrate`; break;
                    case `reverse`: cultureDelta -= 12; throughputDelta -= 14; trustDelta += 4; ds.whipsawed = true; coachKey = `coach_r4_reverse`; break;
                    case `harder`: throughputDelta += 6; trustDelta -= 14; cultureDelta -= 4; ds.overRotated = true; coachKey = `coach_r4_harder`; break;
                }

                // Sequence the 90-day plan.
                switch (d.sequence) {
                    case `phased`: throughputDelta += 8; cultureDelta += 4; roleDelta += 2; break;
                    case `announce`: cultureDelta -= 8; trustDelta -= 4; coachKey = `coach_r4_announce`; break;
                    case `bigbang`: throughputDelta += 2; trustDelta -= 10; ds.overRotated = true; coachKey = `coach_r4_bigbang`; break;
                }

                // Leading indicators to watch.
                switch (d.kpi) {
                    case `balanced`: roleDelta += 8; cultureDelta += 4; trustDelta += 4; break;
                    case `throughputonly`: throughputDelta += 4; trustDelta -= 8; coachKey = `coach_r4_throughputonly`; break;
                    case `satonly`: trustDelta += 4; throughputDelta -= 8; coachKey = `coach_r4_satonly`; break;
                }

                // Steadiness of intent through turbulence.
                if (d.steadiness >= 60) { cultureDelta += 5; trustDelta += 3; }
                else if (d.steadiness <= 30) { cultureDelta -= 6; ds.whipsawed = true; coachKey = `coach_r4_whipsaw`; }

                summaryKey = (d.recovery === `recalibrate` && d.sequence === `phased` && d.kpi === `balanced`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            spend = Math.max(0, spend);
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            ds.slaPenalty = Math.round(ds.slaPenalty + slaHit);

            // A blown budget forces deferred capacity — a real throughput drag.
            if (ds.budgetUsed > this.BUDGET_CAP) {
                throughputDelta -= 8;
                if (coachKey === `coach_default`) coachKey = `coach_budget_over`;
            }
            // SLA penalties signal an external-commitment miss — they erode trust this round.
            if (slaHit > 0) trustDelta -= 4;

            // Apply deltas, clamped 0–100.
            ds.culture = Math.max(0, Math.min(100, ds.culture + cultureDelta));
            ds.throughput = Math.max(0, Math.min(100, ds.throughput + throughputDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.role = Math.max(0, Math.min(100, ds.role + roleDelta));

            ds.cultureHistory.push(Math.round(ds.culture));
            ds.throughputHistory.push(Math.round(ds.throughput));
            ds.trustHistory.push(Math.round(ds.trust));
            ds.roleHistory.push(Math.round(ds.role));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                culture: Math.round(ds.culture),
                cultureDelta: Math.round(cultureDelta),
                throughput: Math.round(ds.throughput),
                throughputDelta: Math.round(throughputDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                role: Math.round(ds.role),
                roleDelta: Math.round(roleDelta),
                budgetUsed: ds.budgetUsed,
                slaPenalty: ds.slaPenalty,
                overRotated: ds.overRotated,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

