        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const culture = Math.round(ds.culture);
            const throughput = Math.round(ds.throughput);
            const trust = Math.round(ds.trust);
            const role = Math.round(ds.role);
            const composite = Math.round(culture * 0.25 + throughput * 0.25 + trust * 0.30 + role * 0.20);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.bothAnd;
            const badge = met
                ? `<span class="cvfsim-cm-badge cvfsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="cvfsim-cm-badge cvfsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const failBadge = s.overRotated
                ? ` <span class="cvfsim-cm-badge cvfsim-cm-no">` + T(`cm_broke`) + `</span>`
                : (s.regulatoryEvent ? ` <span class="cvfsim-cm-badge cvfsim-cm-no">` + T(`cm_reg`) + `</span>`
                : (s.whipsawed ? ` <span class="cvfsim-cm-badge cvfsim-cm-no">` + T(`cm_whipsaw`) + `</span>` : ``));
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="cvfsim-cm-metric"><span class="cvfsim-cm-mv">` + Math.round(s.culture || 0) + `</span><span class="cvfsim-cm-ml">` + T(`cm_m_culture`) + `</span></div>`
                + `<div class="cvfsim-cm-metric"><span class="cvfsim-cm-mv">` + Math.round(s.throughput || 0) + `</span><span class="cvfsim-cm-ml">` + T(`cm_m_throughput`) + `</span></div>`
                + `<div class="cvfsim-cm-metric"><span class="cvfsim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="cvfsim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="cvfsim-cm-metric"><span class="cvfsim-cm-mv">` + Math.round(s.role || 0) + `</span><span class="cvfsim-cm-ml">` + T(`cm_m_role`) + `</span></div>`;
            return ``
                + `<div class="cvfsim-completion">`
                +   `<div class="cvfsim-cm-head">`
                +     `<div class="cvfsim-cm-score">` + score + `<span class="cvfsim-cm-score-max">/100</span></div>`
                +     `<div class="cvfsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="cvfsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="cvfsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="cvfsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const culture = Math.round(ds.culture);
            const throughput = Math.round(ds.throughput);
            const trust = Math.round(ds.trust);
            const role = Math.round(ds.role);

            const composite = Math.round(culture * 0.25 + throughput * 0.25 + trust * 0.30 + role * 0.20);
            const hitThroughput = throughput >= this.TARGET_THROUGHPUT;
            const keptTrust = trust >= 58;
            const bothAnd = hitThroughput && keptTrust && role >= 60 && composite >= this.WIN_COMPOSITE;

            let performanceKey = `grade_stalled`;
            if (bothAnd) performanceKey = `grade_bothand`;
            else if (hitThroughput && !keptTrust) performanceKey = `grade_broke`;
            else if (!hitThroughput && keptTrust) performanceKey = `grade_protected`;
            else if (composite >= 55) performanceKey = `grade_unbalanced`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (bothAnd) insights.push(window.mySimulation.t(`insight_bothand`));
            else if (hitThroughput && !keptTrust) insights.push(window.mySimulation.t(`insight_overrotate`));
            else if (!hitThroughput && keptTrust) insights.push(window.mySimulation.t(`insight_stayclan`));
            else insights.push(window.mySimulation.t(`insight_stalled`));

            if (ds.overRotated) insights.push(window.mySimulation.t(`insight_lostpeople`));
            if (ds.regulatoryEvent) insights.push(window.mySimulation.t(`insight_regulatory`));
            if (ds.whipsawed) insights.push(window.mySimulation.t(`insight_whipsaw`));
            if (role < 45) insights.push(window.mySimulation.t(`insight_lowrole`));
            if (ds.slaPenalty > 0) insights.push(window.mySimulation.t(`insight_sla`));

            return {
                culture: culture,
                throughput: throughput,
                trust: trust,
                role: role,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                hitThroughput: hitThroughput,
                keptTrust: keptTrust,
                bothAnd: bothAnd,
                overRotated: ds.overRotated,
                regulatoryEvent: ds.regulatoryEvent,
                whipsawed: ds.whipsawed,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overRotated) return window.mySimulation.t(`hint_overrotate`);
            if (ds.regulatoryEvent) return window.mySimulation.t(`hint_regulatory`);
            if (ds.role < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_role`);
            if (ds.trust < 35) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.throughput < 45) return window.mySimulation.t(`hint_throughput`);
            if (ds.throughput >= this.TARGET_THROUGHPUT && ds.trust >= 58 && ds.role >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

